const el = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
const today = () => new Date().toLocaleDateString('en-CA');
const people = ['Chill Guide','Hype Coach','Strict Professor','Funny Friend'];
const themes = ['Electric','Midnight','Solar','Glacier','Crimson','Forest'];
const ranks = ['Rookie','Researcher','Scholar','Master','Donezo Legend'];
const classes = () => profile.classes ?? [];
const progressState = () => read('progress-v3',{xp:0,days:[],events:[],tools:{},subjects:{}});
const rank = xp => Math.min(4, Math.floor(xp / 100));
function earn(label, xp, subject, score, tool) {
  const data = progressState();
  data.xp += xp;
  if (!data.days.includes(today())) data.days.push(today());
  data.events.unshift({label,date:today(),xp});
  data.events = data.events.slice(0,50);
  if (tool) data.tools[tool] = (data.tools[tool] ?? 0) + 1;
  if (subject) {
    const prior = data.subjects[subject] ?? {total:0,count:0};
    data.subjects[subject] = {total:prior.total+score,count:prior.count+1,history:[...(prior.history??[]),{date:today(),score}].slice(-100)};
  }
  const previous = rank(data.xp-xp);
  save('progress-v3',data);
  if (rank(data.xp)>previous) {
    const alert = el('#achievement-toast');
    alert.textContent = 'Achievement unlocked · ' + ranks[rank(data.xp)];
    alert.hidden = false;
    setTimeout(()=>alert.hidden=true,4500);
  }
}
function streak(days) {
  const date = new Date();
  if (!days.includes(today())) date.setDate(date.getDate()-1);
  let count = 0;
  while(days.includes(date.toLocaleDateString('en-CA'))) { count++; date.setDate(date.getDate()-1); }
  return count;
}
function field(name,label,type='text',extra='') {
  return '<label>'+label+(type==='textarea'?'<textarea name="'+name+'" '+extra+'></textarea>':'<input name="'+name+'" type="'+type+'" '+extra+'>')+'</label>';
}
function selectField(name,label,options) {
  return '<label>'+label+'<select name="'+name+'">'+options.map(v=>'<option>'+esc(v)+'</option>').join('')+'</select></label>';
}
function section(key,title,icon,description) {
  sections[key]=[title,icon,description];
  nav.insertAdjacentHTML('beforeend','<a href="#'+key+'"><span aria-hidden="true">'+icon+'</span>'+title+'</a>');
}
section('dashboard','Dashboard','▣','Your classes, progress and tutor.');
section('studio','Tool Studio','⊞','Writing, grades, productivity and more.');
section('assignments','Assignments','▤','Track deadlines and plan what to do next.');
section('settings','Settings','⚙','Manage your profile, theme and tutor.');
function applyTheme(){document.documentElement.dataset.theme=(profile.theme ?? 'Electric').toLowerCase();}
function rankTiles(){
  const grid=el('.cards',main);
  if(!grid)return;
  const tools=progressState().tools;
  const tiles=[...grid.querySelectorAll('.tile')];
  tiles.sort((a,b)=>(tools[b.hash.slice(1)]??0)-(tools[a.hash.slice(1)]??0));
  grid.append(...tiles);
}
const toast = document.createElement('div');toast.id='achievement-toast';toast.setAttribute('role','status');toast.hidden=true;document.body.append(toast);

const steps = [
  ['Your profile',field('name','Display name','text','required maxlength="40"')+field('avatar','Upload an avatar (optional)','file','accept="image/png,image/jpeg,image/webp"')],
  ['School level',selectField('grade','Where are you studying?',['Elementary','Middle school','High school','College'])],
  ['Your classes',field('className','Enter one current class','text','required maxlength="55"')+'<p>Free includes one class.</p>'],
  ['Subjects',selectField('subject','What subject is this class?',['Math','English','Science','History','World languages','Other'])],
  ['Goals',field('goal','What would you like to improve?','text','required maxlength="120"')],
  ['Learning style',selectField('style','What helps you learn?',['Worked examples','Visual outlines','Short practice quizzes','Plain-language explanations'])],
  ['Theme',selectField('theme','Choose a theme',themes)],
  ['Tutor',selectField('tutor','Choose your Free tutor',[people[0]])]
];
function setup() {
  const draft={...profile};
  let position=0;
  const panel=el('#setup');
  function renderStep() {
    const [title,fields]=steps[position];
    panel.innerHTML='<p class="eyebrow">Step '+(position+1)+' of '+steps.length+'</p><h2>'+title+'</h2><form class="stack">'+fields+'<p role="status" id="setup-status"></p><div class="actions">'+(position?'<button class="ghost" id="back-step" type="button">Back</button>':'')+'<button class="primary">'+(position===steps.length-1?'Finish setup':'Continue')+'</button></div></form>';
    const form=el('form',panel);
    for(const item of form.elements){if(item.name && item.type!=='file' && draft[item.name])item.value=draft[item.name];}
    const back=el('#back-step',panel);
    if(back) back.onclick=()=>{position--;renderStep();};
    form.onsubmit=async event=>{
      event.preventDefault();
      const data=new FormData(form);
      for(const [key,value] of data) if(typeof value==='string') {
        if(!value.trim()) {el('#setup-status').textContent='Enter a value to continue.';return;}
        draft[key]=value.trim();
      }
      const avatar=data.get('avatar');
      if(avatar?.size){
        if(avatar.size>350000 || !/^image\/(png|jpeg|webp)$/.test(avatar.type)){el('#setup-status').textContent='Use a PNG, JPEG or WebP under 350 KB.';return;}
        try {draft.avatar=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(avatar);});}
        catch {el('#setup-status').textContent='Could not read this image.';return;}
      }
      if(position+1<steps.length){position++;renderStep();return;}
      draft.classes=[{name:draft.className,subject:draft.subject}];
      draft.referral=draft.referral ?? ((draft.name.match(/[a-z0-9]/gi)??['D','Z']).join('').slice(0,16).toUpperCase()+String(crypto.getRandomValues(new Uint32Array(1))[0]%900000+100000));
      profile=draft;
      save('profile',profile);profileLabel();applyTheme();show();
    };
  }
  renderStep();
}
function classRows() {
  const recorded=progressState().subjects;
  return classes().map(item=>{
    const data=recorded[item.name];
    return {...item,pct:data ? Math.round(100*data.total/data.count) : null};
  }).sort((a,b)=>(a.pct??101)-(b.pct??101));
}
