views.studio=()=>`<section class="panel stack"><h2>Choose a tool</h2><form id="studio-picker">${selectField('tool','Tool',toolNames)}</form><div class="actions"><a class="ghost" href="#learn">Flashcard Maker</a><a class="ghost" href="#school">Math Step Solver</a><a class="ghost" href="#projects">Homework Planner</a><a class="ghost" href="#assignments">Assignment Tracker</a></div></section><div class="columns"><section class="panel" id="studio-tool"></section><section class="panel stack" id="studio-result" aria-live="polite"><h2>Your result</h2><p>Choose a tool to get started.</p></section></div><section class="panel stack"><h2>Pomodoro Focus Timer</h2><label>Focus minutes<input id="focus-minutes" type="number" min="1" max="90" value="25"></label><div class="answer" id="focus-clock"></div><p id="focus-status" role="status"></p><div class="actions"><button id="focus-start" class="primary">Start focus</button><button id="focus-pause" class="ghost">Pause</button><button id="focus-reset" class="ghost">Reset</button></div></section>`;
let focusInterval;
function refreshFocus(){
  const clock=el('#focus-clock');
  if(focusEnd){
    remainingSeconds=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));
    if(!remainingSeconds){
      focusEnd=0;earn('Focus session',10);
      if(el('#focus-status'))el('#focus-status').textContent='Focus session complete. Take a short break.';
    }
  }
  if(clock)clock.textContent=Math.floor(remainingSeconds/60)+':'+String(remainingSeconds%60).padStart(2,'0');
}
bindings.studio=()=>{
  const picker=el('#studio-picker').elements.tool;
  picker.value=read('studio-tool',toolNames[0]);
  const area=el('#studio-tool'), result=el('#studio-result');
  function tool(){
    const name=picker.value;
    save('studio-tool',name);
    const [fields,why,build]=studio[name];
    result.innerHTML='<h2>Your result</h2><p>Fill in the inputs to continue.</p>';
    area.innerHTML='<form class="stack"><h2>'+esc(name)+'</h2>'+fields+'<label class="remove-avatar"><input type="checkbox" name="learn" '+((typeof withinStudyHours!=='function'||!scheduledStudy().enabled||withinStudyHours())?'checked':'')+'> Learn Mode</label><button class="primary">Continue</button></form>';
    el('form',area).onsubmit=event=>{
      event.preventDefault();const form=event.currentTarget;
      const data=Object.fromEntries(new FormData(form));
      try{
        const output=build(data);
        const disclose=()=>{
          result.innerHTML='<h2>Result</h2><div class="result-copy">'+esc(output)+'</div><details><summary>Why this works</summary><p>'+esc(why)+'</p></details><details><summary>Explain it like I’m 10</summary><p>Try this with a tiny example first. '+esc(why)+'</p></details><details><summary>Quiz me</summary><p>Can you explain the method in your own words and use it on a different example?</p><details><summary>Check your explanation</summary><p>'+esc(why)+'</p></details></details>'+
          (name==='Read It To Me'?'<div class="actions"><button id="read-text" class="primary">Read aloud</button><button id="stop-text" class="ghost">Stop</button></div><p id="reading-status" role="status"></p>':'');
          if(name==='Read It To Me'){
            el('#read-text').onclick=()=>{
              if(!('speechSynthesis' in window)){el('#reading-status').textContent='Speech is unavailable on this browser.';return;}
              speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(output));
            };
            el('#stop-text').onclick=()=>window.speechSynthesis?.cancel();
          }
          earn(name,5,null,null,'studio');
        };
        if(data.learn){
          result.innerHTML='<h2>Work through it</h2><ol class="steps"><li>Identify the input and what you want to produce.</li><li>'+esc(why)+'</li><li>Predict what a good result should include.</li></ol><button id="reveal-result" class="primary">Reveal result</button>';
          el('#reveal-result').onclick=disclose;
        }else disclose();
      }catch(error){result.innerHTML='<h2>Check your input</h2><p class="problem">'+esc(error.message)+'</p>';}
    };
  }
  picker.onchange=tool;
  tool();
  function resetTimer(){
    const input=el('#focus-minutes');
    if(!input.reportValidity())return false;
    focusEnd=0;remainingSeconds=(Number(input.value)||25)*60;refreshFocus();return true;
  }
  el('#focus-start').onclick=()=>{
    if(focusEnd)return;
    if((remainingSeconds===0 || !focusInterval) && !resetTimer())return;
    focusEnd=Date.now()+remainingSeconds*1000;
    el('#focus-status').textContent='Focus session running.';
    clearInterval(focusInterval);focusInterval=setInterval(refreshFocus,250);refreshFocus();
  };
  el('#focus-reset').onclick=()=>{if(resetTimer())el('#focus-status').textContent='Timer reset.';};
  el('#focus-pause').onclick=()=>{if(focusEnd){refreshFocus();focusEnd=0;el('#focus-status').textContent='Paused.';}};
  el('#focus-minutes').onchange=()=>{if(!focusEnd)resetTimer();};
  refreshFocus();
};
