bindings.learn=()=>{
  oldBindLearn();
  let ratings=read('flash-ratings',{});
  function tally(){const deck=read('deck',[]);const counts=deck.reduce((acc,card)=>{const value=ratings[JSON.stringify(card)];if(value)acc[value]++;return acc;},{known:0,still:0});el('#flash-progress').textContent=deck.length?counts.known+' known · '+counts.still+' still learning':'';}
  function rate(value){
    const deck=read('deck',[]);
    const index=Number(el('#card-count').textContent.match(/Card (\d+)/)?.[1])-1;
    const card=deck[index];
    if(!card)return;
    const key=JSON.stringify(card);
    if(ratings[key]!==value){ratings={...ratings,[key]:value};save('flash-ratings',ratings);earn('Flashcard review',2,classes()[0]?.name,value==='known'?1:0,'learn');}
    el('#next').click();
    tally();
  }
  el('#know').onclick=()=>rate('known');el('#still').onclick=()=>rate('still');
  const form=el('#deck-form'), submit=form.onsubmit;form.onsubmit=event=>{submit(event);tally();};
  tally();
};
