  const base=40+5*i,percent=10+5*(i%4),amount=base*(1+percent/100);
  const money=n=>'$'+n.toFixed(2);
  practice['Applied Math'].push(question('A price of '+money(base)+' rises by '+percent+'%. What is the new price?',money(amount),[money(base),money(amount+5),money(amount-2)],'Multiply '+money(base)+' by '+(1+percent/100)+'.',i));
