const practiceCount=Object.values(practice).reduce((n,bank)=>n+bank.length,0);
let drillInterval;
views.test=()=>`<div class="columns"><section class="panel stack"><h2>Practice sections</h2><p>${practiceCount} questions with explanations. Timed mini-tests use five questions from a selected section.</p><form id="practice-form" class="stack">${selectField('section','Section',Object.keys(practice))}<label class="remove-avatar"><input name="timed" type="checkbox"> Timed mini-test (5 minutes)</label><button class="primary">Start practice</button></form></section><section id="drill-result" class="panel stack"><h2>Ready when you are</h2></section></div><div class="columns"><section class="panel stack"><h2>Strategy cards</h2>${Object.entries(strategies).map(([name,body])=>'<details><summary>'+name+'</summary><p>'+body+'</p></details>').join('')}</section><section class="panel stack"><h2>Score goal tracker</h2><form id="score-goal" class="stack">${selectField('exam','Exam',['400–1600 scale','1–36 scale'])}${field('baseline','Current score','number','required')}${field('goal','Target score','number','required')}<button class="ghost">Save goal</button></form><p id="goal-status" role="status"></p></section></div><section class="panel"><h2>Word Vault · ${wordVault.length} words</h2>${wordVault.map(([word,def,example,hook])=>'<details><summary>'+word+'</summary><p>'+def+'. '+example+'</p><p>Memory hook: '+hook+'</p></details>').join('')}</section>`;
bindings.test=()=>{
  const output=el('#drill-result');
  el('#practice-form').onsubmit=event=>{
    event.preventDefault();
    clearInterval(drillInterval);
    const {section:name,timed}=Object.fromEntries(new FormData(event.currentTarget));
    const bank=practice[name];
    const start=Math.floor(Math.random()*bank.length);
    const questions=timed?Array.from({length:5},(_,i)=>bank[(start+i)%bank.length]):bank;
    const misses=[];
    let index=0,score=0,answered=0;
    const end=Date.now()+300000;
    function finish(expired=false){
      clearInterval(drillInterval);
      if(answered){
        const subject=/Math/.test(name)?'Math':/Science/.test(name)?'Science':'English';
        const current=(typeof allClasses==='function'?allClasses():classes()).find(item=>item.subject===subject);
        earn(name+' practice',10,current?.name,score/answered,'test');
      }
      output.innerHTML='<h2>'+(expired?'Time is up':'Practice complete')+'</h2><p class="answer">'+score+' / '+questions.length+'</p><p>'+answered+' answered</p>'+(misses.length?'<h3>Review these weak spots</h3><ol class="steps">'+misses.map(([prompt,why])=>'<li>'+esc(prompt)+' '+esc(why)+'</li>').join('')+'</ol>':'<p>'+ (answered?'No missed answers among attempted questions.':'No attempts recorded.')+'</p>');
    }
    function showQuestion(){
      if(index===questions.length){finish();return;}
      const [prompt,choices,correct,why]=questions[index];
      output.innerHTML='<p class="eyebrow">Question '+(index+1)+' of '+questions.length+'</p><p id="drill-clock"></p><h2>'+esc(prompt)+'</h2>'+choices.map((c,i)=>'<button class="ghost" data-answer="'+i+'">'+esc(c)+'</button>').join('')+'<p role="status" id="check-answer"></p><button id="drill-next" class="primary" hidden>'+(index+1===questions.length?'Show results':'Next question')+'</button>';
      const buttons=[...output.querySelectorAll('[data-answer]')];
      buttons.forEach(button=>button.onclick=()=>{
        buttons.forEach(b=>b.disabled=true);answered++;
        if(+button.dataset.answer===correct)score++;else {misses.push([prompt,why]);if(typeof recordMistake==='function')recordMistake(name,prompt,choices[correct],why);}
        el('#check-answer').textContent=(+button.dataset.answer===correct?'Correct. ':'Answer: '+choices[correct]+'. ')+why;
        el('#drill-next').hidden=false;el('#drill-next').focus();
      });
      el('#drill-next').onclick=()=>{index++;showQuestion();const heading=el('h2',output);heading.tabIndex=-1;heading.focus({preventScroll:true});};
    }
    function tick(){
      if(!output.isConnected){clearInterval(drillInterval);return;}
      const remaining=Math.max(0,Math.ceil((end-Date.now())/1000));
      if(!remaining){finish(true);return;}
      const clock=el('#drill-clock');if(clock)clock.textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0')+' remaining';
    }
    showQuestion();if(timed){tick();drillInterval=setInterval(tick,500);}
  };
  function showGoal(state){el('#goal-status').textContent=state.exam+' target: '+state.goal+' · '+Math.max(0,state.goal-state.baseline)+' points to close.';}
  const form=el('#score-goal');
  const saved=read('score-goal',null);
  if(saved){for(const [key,value] of Object.entries(saved))form.elements[key].value=key==='exam'?({SAT:'400–1600 scale',ACT:'1–36 scale'}[value]??value):value;showGoal({...saved,exam:form.elements.exam.value});}
  form.onsubmit=event=>{
    event.preventDefault();const data=Object.fromEntries(new FormData(form));
    const [min,max,step]=data.exam==='400–1600 scale'?[400,1600,10]:[1,36,1];
    if([data.baseline,data.goal].some(v=>+v<min||+v>max||+v%step)){el('#goal-status').textContent='Use '+min+'–'+max+' in increments of '+step+'.';return;}
    save('score-goal',data);showGoal(data);
  };
};
