function checkEquation(input,solution){
  const sides=input.toLowerCase().replace(/\s|\*/g,'').replace(/−/g,'-').replace(/²/g,'^2').split('=');
  const roots=[...solution[0].matchAll(/x = (-?(?:\d+(?:\.\d+)?)(?:e[+-]?\d+)?)/gi)].map(match=>+match[1]);
  if(!roots.length)return null;
  function calculate(side,x){
    const terms=(/^[+-]/.test(side)?side:'+'+side).match(/[+-][^+-]+/g);
    return terms.reduce((total,term)=>{
      const sign=term.startsWith('-')?-1:1;
      const [coefficient,power]=term.slice(1).split('x');
      return total+sign*(coefficient===''?1:Number(coefficient))*(power===undefined?1:power==='^2'?x*x:x);
    },0);
  }
  const checks=roots.map(x=>{const a=calculate(sides[0],x),b=calculate(sides[1],x);return {x,a,b,ok:Math.abs(a-b)<=1e-6*Math.max(1,Math.abs(a),Math.abs(b))};});
  return checks.every(check=>check.ok)?checks.map(({x,a,b})=>'x = '+x+' → left ≈ '+round(a)+', right ≈ '+round(b)).join(' · '):null;
}
