bindings.snap=()=>{
  const form=el('#confirm-snap'), result=el('#snap-result');
  const usage=()=>{const data=read('snap-limit',{});return data.date===today()?data.count:0;};
  const quota=()=>el('#snap-limit').textContent=Math.max(0,3-usage())+' of 3 Free snaps left today on this browser.';
  quota();
  form.elements.equation.oninput=()=>form.elements.confirmed.checked=false;
  el('#snap-example').onclick=()=>{form.elements.equation.value='2x² + 5x − 12 = 0';form.elements.confirmed.checked=false;form.elements.equation.focus();};
  let scan=0;
  el('#snap-photo').onchange=async event=>{
    const step=++scan;
    const img=el('#photo-preview'),status=el('#ocr-status'),file=event.currentTarget.files[0];
    if(photoUrl)URL.revokeObjectURL(photoUrl);
    img.hidden=!file;
    form.elements.confirmed.checked=false;
    form.elements.equation.value='';
    result.innerHTML='<h2>Answer and steps</h2><p>Confirm a question to get started.</p>';
    const controls=[...form.querySelectorAll('textarea,input,button')];
    controls.forEach(control=>control.disabled=!!file);
    if(!file){status.textContent='Choose a clear photo or type the question.';return;}
    photoUrl=URL.createObjectURL(file);img.src=photoUrl;
    try{
      const question=await recognizeHomework(file,percent=>{
        if(step===scan&&form.isConnected)status.textContent=percent===null?'Loading automatic extraction…':'Extracting text · '+percent+'%';
      });
      if(step!==scan||!form.isConnected)return;
      if(question)form.elements.equation.value=question.slice(0,500);
      status.textContent=question?'Text extracted. Correct any errors before confirming.':'I couldn’t read this photo. Retake it or type the question below.';
    }catch{if(step===scan&&form.isConnected)status.textContent='I couldn’t read this photo. Retake it or type the question below.';}
    finally{if(step===scan)controls.forEach(control=>control.disabled=false);}

  };
  form.onsubmit=event=>{
    event.preventDefault();
    if(!form.elements.confirmed.checked||form.elements.confirmed.disabled)return;
    if(usage()>=3){result.innerHTML='<h2>Daily limit reached</h2><p>Free allows three successful solutions per day in this browser.</p><a href="#pricing" class="ghost">View plans</a>';return;}
    const input=form.elements.equation.value.trim();
    const answer=finalTutorAnswer(input);
    if(!answer){result.innerHTML='<h2>Answer unavailable</h2><p>This solver supports arithmetic, percentages, and linear or quadratic equations in x. For other questions, use the extracted text in your study notes.</p>';return;}
    save('snap-limit',{date:today(),count:usage()+1});quota();
    const proof=answer.check,equation=input.includes('='),percentage=/%/.test(input);
    const lesson=equation?'Apply the same change to both sides to preserve equality. Substitution tests the proposed solution.':percentage?'A percentage is a rate per 100. Divide the rate by 100 and multiply by the whole.':'The order of operations gives a consistent answer. Work inside parentheses first, then powers, multiplication and division, and finally addition and subtraction.';
    const simple=equation?'An equation is a balance. To keep it balanced, do the same thing on each side.':percentage?'Twenty percent means 20 out of every 100. Find that same fraction of the amount in your problem.':'Think of parentheses as a box. Solve what’s inside the box before using the result outside it.';
    const practice=equation?['3x + 6 = 18','x² − 9 = 0','x = 4','x = 3 or x = −3']:percentage?['25% of 80','12% of 250','20','30']:['4 × (8 − 3)','2³ + 6 ÷ 2','20','11'];
    result.innerHTML='<h2>Answer</h2><div class="answer">'+esc(answer.answer)+'</div><p class="'+(proof?'status':'notice')+'">'+(proof?'Double-Checked ✓ · '+esc(proof):'No independent check for this result.')+'</p><h3>How you get there</h3><ol class="steps">'+answer.steps.map(step=>'<li>'+esc(step)+'</li>').join('')+'</ol><details><summary>Why this works</summary><p>'+lesson+'</p></details><details><summary>Explain it like I’m 10</summary><p>'+simple+'</p></details><details><summary>Quiz me · two practice problems</summary><p>1. '+practice[0]+'<br>2. '+practice[1]+'</p><details><summary>Check answers</summary><p>1. '+practice[2]+'<br>2. '+practice[3]+'</p></details></details>';
    earn('Solved with Snap It',5,null,null,'snap');
  };
};
