bindings.capture=()=>{
  oldBindCapture();
  const status=el('#media-status'), transcript=el('#transcript'), output=el('#media-output'), media=el('#media-preview');
  const start=el('#capture-start'),stop=el('#capture-stop');
  let recognition,stream,recorder,mediaUrl,pending=[];
  const onRoute=()=>{
    if(recorder?.state==='recording')recorder.stop();
    recognition?.abort();
    stream?.getTracks().forEach(track=>track.stop());
    if(mediaUrl)URL.revokeObjectURL(mediaUrl);
  };
  window.addEventListener('hashchange',onRoute,{once:true});
  function flags(){
    const matches=sentences(transcript.value).filter(s=>/\b(important|remember|on the test|write this down|due|make sure|key point)\b/i.test(s)).slice(-8);
    el('#emphasis').innerHTML=matches.map(line=>'<li>Teacher said it matters · '+esc(line)+'</li>').join('');
  }
  function showMedia(file){
    if(mediaUrl)URL.revokeObjectURL(mediaUrl);
    mediaUrl=URL.createObjectURL(file);media.src=mediaUrl;media.hidden=false;
  }
  transcript.oninput=flags;
  el('#media-file').onchange=event=>{
    const file=event.currentTarget.files[0];
    if(file){showMedia(file);status.textContent='Recording loaded. Paste or type the transcript for in-page processing.';}
  };
  start.onclick=async()=>{
    const Engine=window.SpeechRecognition??window.webkitSpeechRecognition;
    start.disabled=true;
    try{
      stream=await navigator.mediaDevices.getUserMedia({audio:true});
      if(!start.isConnected){stream.getTracks().forEach(track=>track.stop());return;}
      const chunks=[];
      recorder=new MediaRecorder(stream);
      recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};
      recorder.onstop=()=>{if(chunks.length&&media.isConnected)showMedia(new Blob(chunks,{type:recorder.mimeType}));};
      recorder.start();
      stop.disabled=false;
      status.textContent=Engine?'Recording and listening for emphasis.':'Recording. Live transcription is unavailable in this browser.';
      if(Engine){
        recognition=new Engine();recognition.continuous=true;recognition.lang='en-US';
        recognition.onresult=event=>{
          for(let i=event.resultIndex;i<event.results.length;i++)if(event.results[i].isFinal){
            const phrase=event.results[i][0].transcript.trim();
            transcript.value=(transcript.value+' '+phrase+(/[.!?]$/.test(phrase)?'':'.')).trim().slice(0,16000);
          }
          flags();
        };
        recognition.onerror=()=>status.textContent='Audio is still recording. Browser transcription is unavailable.';
        try{recognition.start();}catch{status.textContent='Audio is still recording. Browser transcription could not start.';}
      }
    }catch{stream?.getTracks().forEach(track=>track.stop());start.disabled=false;status.textContent='Microphone recording is unavailable. You can upload a file or paste a transcript.';}
  };
  stop.onclick=()=>{
    if(recorder?.state==='recording')recorder.stop();
    try{recognition?.stop();}catch{}
    stream?.getTracks().forEach(track=>track.stop());
    start.disabled=false;stop.disabled=true;status.textContent='Recording stopped. Review the transcript below.';
  };
  document.querySelectorAll('[data-capture-output]').forEach(button=>button.onclick=()=>{
    const name=button.dataset.captureOutput,text=transcript.value.trim();
    const due=el('#capture-due');due.hidden=true;
    if(!text){output.textContent='Add a transcript first.';return;}
    const phrases=sentences(text).slice(0,20);
    if(name==='Make My Notes')output.textContent=studio['Lecture Notes Organizer'][2]({text:phrases.join('\n')});
    if(name==='Summarize It')output.textContent=studio.Summarizer[2]({text});
    if(name==='Build My Project')output.textContent=studio['Research Paper Kit'][2]({text:phrases[0]??text});
    if(name==='Flashcards'){
      const deck=phrases.map(line=>[line.split(/\s+/).slice(0,4).join(' ')+'…',line]);
      output.textContent=deck.map(card=>card.join(' | ')).join('\n')+'\n\nCopy these into Learn to review or edit them.';
    }
    if(name==='Assignment Mode'){
      pending=phrases.filter(line=>/\b(submit|write|read|bring|turn in|finish|complete|due|prepare|review)\b/i.test(line));
      if(!pending.length)pending=phrases.slice(0,5);
      output.textContent=listText(pending);
      const detected=text.match(/\b(20\d\d-\d\d-\d\d)\b/)?.[1]??'';
      el('#record-due').value=detected;
      due.hidden=false;
    }
  });
  el('#save-record-tasks').onclick=()=>{
    if(!pending.length)return;
    const stored=pending.map(task=>addAssignment(task.slice(0,140),el('#record-due').value)).every(Boolean);
    output.textContent=pending.length+' items added to Assignments.'+(stored?'':' Some changes may last only for this visit.');
    pending=[];el('#capture-due').hidden=true;
  };
};
